[SPECIALIST_FINDING]
{
  "specialty": "kdoctor-pulmonology",
  "answer": "운동 시 호흡곤란이 수 주간 진행하는 55세 남성·용접흄 15년 노출력에서, 우선 배제할 것은 (1) 노출과 무관하게 생명을 위협하는 시간민감 질환 — 관상동맥질환/심부전 등 심장 원인, 폐색전증, 악성 종양(폐암·중피종), 활동성 결핵 — 이고, (2) 그 다음이 직업성 폐질환 축(용접흄 관련 폐렴/금속흄열, COPD, 과민성 폐렴, 폐섬유화증)이다. 필요한 검사는 흉부 고해상도 CT(HRCT) + 폐기능검사(기관지확장제 반응 포함) + 심장 평가(심전도·심초음파, 필요시 운동부하/관상동맥 평가) + 산소포화도/6분 보행, 그리고 직업력 정밀 청취와 노출물질 SDS 확인이다.",

  "red_flag": {
    "present": false,
    "items": []
  },

  "hypotheses": [
    {
      "name": "관상동맥질환/심부전 등 심장성 호흡곤란",
      "icd10": "I25.1 / I50.9",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "운동 시 호흡곤란은 심장성 호흡곤란의 전형적 양상 중 하나", "basis": "history" },
        { "text": "55세 전후 남성 = 관상동맥질환 위험군 연령·성", "basis": "history" },
        { "text": "용접흄 노출군에서 흡연 동반 가능성이 흔함(추정 — 흡연력 입력 없음)", "basis": "history" }
      ],
      "against": [
        { "text": "흉통·기좌호흡·야간 발작성 호흡곤란·부종·심계항진 정보 없음", "basis": "history" },
        { "text": "심전도·심초음파·BNP 결과 없음", "basis": "measurement" }
      ]
    },
    {
      "name": "폐색전증",
      "icd10": "I26",
      "must_not_miss": true,
      "probability_band": "low",
      "supports": [
        { "text": "운동 시 호흡곤란은 폐색전증의 비특이 증상 중 하나", "basis": "history" }
      ],
      "against": [
        { "text": "최근 수술·장거리 이동·하지 부종·흉통·실신 정보 없음", "basis": "history" },
        { "text": "D-dimer·CTPA 결과 없음", "basis": "measurement" }
