        { "text": "노출 후 수 시간 내 발열·근육통·기침 패턴이 전형", "basis": "guideline" }
      ],
      "against": [
        { "text": "수 주간 지속되는 운동 시 호흡곤란은 금속흄열의 자기한정성 경과와 불일치", "basis": "history" }
      ]
    },
    {
      "name": "용접흄폐렴/폐섬유화증(망간·철 흄 관련 간질성 폐질환)",
      "icd10": "J63.8 / J84.9",
      "must_not_miss": false,
      "probability_band": "medium",
      "supports": [
        { "text": "15년 용접흄 누적 노출", "basis": "history" },
        { "text": "서서히 진행하는 운동 시 호흡곤란", "basis": "history" }
      ],
      "against": [
        { "text": "HRCT·폐기능(DLCO)·6분 보행 결과 없음", "basis": "measurement" },
        { "text": "직업력의 흄·가스 조성 SDS·환기·보호구 정보 없음", "basis": "history" }
      ]
    },
    {
      "name": "폐동맥고혈압/수면 무호흡",
      "icd10": "I27.0 / G47.33",
      "must_not_miss": false,
      "probability_band": "low",
      "supports": [
