{
  "specialty": "kdoctor-occupational-environmental",
  "answer": "확인해야 할 핵심 노출 항목은 흄·분진의 종류(금속 흄·아크 용접 흄·가스, 피복재·플럭스 성분, 갈바나이즈·도장·스테인리스 등 모재와 용접법), 작업장 환기(국소배기·전체환기·밀폐도), 보호구(마스크 등급이 아닌 '착용 여부·밀착·교체 주기'), 노출 기간·빈도·작업 위치, 그리고 동료 증상 유무입니다. 업무관련성 판정은 이 SP가 하지 않으며, 직업환경의학과·산업보건 담당자·근로복지공단 등 공식 경로를 통해서만 판단됩니다.",
  "red_flag": {
    "present": false,
    "items": [
      { "id": "O2-candidate", "evidence": "신규 호흡곤란(용접공 15년) — 급성 호흡곤란·흉통·쌕쌕거림이나 아크 용접 직후 금속흄 노출 후 증상 발생 시 응급", "basis": "history" }
    ]
  },
  "hypotheses": [
    {
      "name": "직업성 천식(용접 흄·가스 관련)",
      "icd10": "J45.9",
      "must_not_miss": false,
      "probability_band": "medium",
      "supports": [
        { "text": "용접공 15년 — 금속흄·가스(오존·NOx·CO)·플럭스 흄 만성 노출", "basis": "history" },
        { "text": "신규 호흡곤란 발생", "basis": "history" }
      ],
      "against": [
        { "text": "작업·휴일 시간 관계 및 가역성 여부 미확인", "basis": "history" },
        { "text": "객관적 폐기능·기관지유발검사 정보 없음", "basis": "measurement" }
      ]
    },
    {
      "name": "금속흄열(metal fume fever)",
      "icd10": "T56.9 또는 별도 코드 미상",
      "must_not_miss": false,
      "probability_band": "medium",
      "supports": [
        { "text": "용접 흄 노출 — 특히 갈바나이즈(아연) 용접 시 전형", "basis": "history" }
      ],
      "against": [
        { "text": "발열·오한·근육통·발병 시간(노출 후 4~12시간) 여부 미확인", "basis": "history" }
      ]
    },
    {
      "name": "직업성 과민성 폐렴(금속·이소시아네이트·플럭스 등 항원)",
      "icd10": "J67.9",
      "must_not_miss": true,
      "probability_band": "low",
      "supports": [
        { "text": "15년 누적 노출에서 새 항원 감작 가능", "basis": "history" }
      ],
      "against": [
        { "text": "영상·폐기능·항원 특정 정보 없음", "basis": "image" }
      ]
    },
    {
      "name": "용접공 폐(진폐·siderosis) 등 만성 간질성 변화",
      "icd10": "J62.8 등",
      "must_not_miss": false,
      "probability_band": "medium",
      "supports": [
        { "text": "15년 장기 용접 흄 노출", "basis": "history" }
      ],
      "against": [
        { "text": "흉부 영상·폐기능 데이터 없음", "basis": "image" }
