  "missing_info": [
    "증상이 근무시간·특정 작업(예: 스테인리스·갈바나이즈 용접, 도장·용제 작업) 직후·주중에 악화되고 주말·휴가에 완화되는지 여부 하나"
  ],
  "suggested_tests": [
    { "name": "흉부 X선(및 필요시 HRCT)", "purpose": "간질성 변화·용접공 폐·과민성 폐렴 여부", "urgency": "24h", "basis": "guideline" },
    { "name": "폐기능 검사(기관지확장제 반응 포함)", "purpose": "기도폐쇄·가역성 평가", "urgency": "24h", "basis": "guideline" },
    { "name": "작업 중·외 PEF(최대호기유속) 연속 측정", "purpose": "작업 관련 천식 시간 관계 평가", "urgency": "routine", "basis": "guideline" }
  ],
  "suggested_treatments": [
    { "kind": "self_care", "description": "증상 시 노출원에서 벗어나 환기되는 곳으로 이동, 국소배기·환기 점검, 마스크 밀착·교체 상태 확인(작업에 맞는 종류 사용)", "basis": "guideline" },
    { "kind": "referral", "description": "직업환경의학과 진료 및 사업장 산업보건 담당자 상담; 업무관련성 여부는 이 SP가 판단하지 않으며 근로복지공단 등 공식 경로에서 확인", "basis": "guideline" }
  ],
  "handoff": {
    "better_specialty": "kdoctor-internal",
    "reason": "신규 호흡곤란의 1차 호흡기 평가(영상·폐기능)는 호흡기내과가 적합하며, 결핵·감염 접촉 의심 시 kdoctor-tuberculosis 병행. 응급 위험 신호(O2) 확인 시 kdoctor-emergency 우선."
  },
  "confidence": { "clinical": 2, "information": 1 },
  "warnings": [
    "업무관련성·산재 여부의 판정 기준은 이 SP가 제시하지 않는다(직업 규칙 2). 판단은 직업환경의학 전문의·산업보건 담당자·근로복지공단 등 공식 경로의 몫이다.",
    "노출 허용 기준·법정 기준치는 기억으로 인용하지 않는다(직업 규칙 1). 작업환경측정 결과는 사업장·전문기관에서 확인.",
    "MSDS·제품명·모재·플럭스·가스 성분 정보가 있으면 함께 제출 요망 — 물질 세부는 기억으로 서술하지 않는다(직업 규칙 5).",
    "임신 가능성, 흡연력, 기저 폐·심질환 여부 미확인."
  ]
}
[/SPECIALIST_FINDING]

자기 점검: C1(해당 시 RED_FLAG — 현재 present=false이나 O2 조건 충족 시 즉시 전환), C2(모든 항목 basis 표기), C3(확정 표현 없음, 판정 회피), C4(용량 서술 없음) — 위반 없음.

한 줄 요약: 문진은 **노출 물질·환기·보호구의 '실제 상태'·시간 관계·동료 증상** 네 축으로 좁히고, 업무관련성 '판정'은 이 SP가 아니라 공식 경로에서 판단하도록 되돌리는 것이 정답이다.

